C["en"]["FAQ"] = [
 ("indoor", "Is the vehicle stored indoors or outdoors?", "All our spaces are **indoors**, inside closed sheds. We do not offer outdoor spaces."),
 ("insurance", "Is my vehicle insured?", "Yes. While in storage your vehicle is covered by an insurance policy for theft, fire, lightning and explosion, vandalism, weather events and damage caused by moving vehicles inside the storage area.\n\nCompensation is capped at **25,000 € per vehicle** (except in cases of wilful misconduct or gross negligence) and cannot exceed the market value of the vehicle at the time of the damage. Not covered: damage caused by gas bottles or flammable materials left in the vehicle, damage occurring on the day of collection or return, and wear (tyres, jockey wheel, plastics). Details are in the contract."),
 ("hours", "When is the storage open?", "The storage is open **from 1 April to 1 October**: during this period you can collect and return your vehicle. **From 1 October to 1 April it is closed**: you cannot take your vehicle out or enter the storage area.\n\nWe receive visitors by appointment."),
 ("pickup", "How do I collect my vehicle?", "Tell us at least **one week ahead** (by email or in the customer area) which day you want it. We confirm and prepare the vehicle.\n\nOn the day you find it parked outside the shed, in an open area that is easy to reach, and you can take it yourself **from 8:30**. If you have not collected it by 17:00 it stays outside and is no longer our responsibility. If you need it before 8:30 we prepare it the day before.\n\nIf you tell us with less than one week's notice we cannot guarantee it will be ready; if we manage anyway, a 50 € surcharge applies. Two exits per season are included."),
 ("return", "How do I bring it back?", "Write to us the day you want to bring it back and leave it in the outside areas: do not lock the drawbar with padlocks or chains, leave no flammable material inside, park without blocking other vehicles and take photos.\n\nWe move it indoors by 17:00 the same day. If it arrives after 16:30 it stays outside until the next day and is not our responsibility in the meantime. Remember the storage is closed after 1 October."),
 ("payment", "How and when do I pay?", "A **deposit** (usually 50 €) confirms your space. The **balance** is due by **30 September**, before you bring the vehicle back for the winter; after that date 100 € is added.\n\nYou can pay by bank transfer, at the office by appointment or, in the customer area, by card or iDEAL. Paying in full is what allows you to collect the vehicle the following year."),
 ("booking", "How do I book a space?", "Write to us with the contact form telling us what vehicle you have and how long it is: we reply with price and availability. If services and prices suit you, you become a customer with an ID document, the vehicle registration document and your signed contract.\n\nEvery April we write to you to book your space: the deposit must be paid by the date in the email, otherwise you lose the space."),
 ("documents", "Which documents do I need?", "You need a valid personal document (passport, driving licence or ID card), the vehicle registration document and your signed contract, with the privacy notice acknowledged. Existing customers can upload documents in the customer area."),
 ("included", "What is included in the annual fee?", "Included are insurance, **1 standard wash**, **2 exits per season** and a check of tyre pressure, lights and brakes. The space is always indoors and guarded 24 hours a day."),
 ("washing", "Is washing included?", "Yes, the annual fee includes 1 standard wash of the vehicle, done at the first collection of the season."),
 ("security", "How is the storage protected?", "Video surveillance 24 hours a day with recording, perimeter alarms linked to a control centre, fences with access control and night lighting."),
 ("gas", "Can I leave gas bottles in the vehicle?", "No. Flammable or explosive materials such as gas bottles may not be left in the vehicle: if we find any, a penalty of **200 € per bottle** applies. We no longer offer gas bottle storage."),
 ("extras", "Are there extra costs?", "In some cases: **100 €** if the balance arrives after 30 September, **50 €** if you tell us about collection with less than one week's notice, **50 €** for each exit beyond the 2 included. Transport is charged separately (see the prices)."),
 ("location", "Where are you?", "We have two sites: **Camporengo**, Località Camporengo 4, Cavaion Veronese (VR), and **Casalmenini**, Strada Provinciale 29 no. 12, Rivoli Veronese (VR). We will tell you which site your vehicle is at."),
 ("contact", "How do I contact you?", "Write with the contact form or call **" + PHONE1 + "** or **" + PHONE2 + "**. Email: " + EMAIL + "."),
 ("login", "How do I enter the customer area?", "Press «Customer area» and enter the email you are registered with: we send you a 6-digit code. There you see your account and receipts, book your exit, upload documents and pay online. It works only for customers who are already registered."),
 ("about", "Who are you?", "Garda Center is a family-run business: indoor storage for caravans, boats and jet skis in Cavaion Veronese and Rivoli Veronese, on Lake Garda."),
]
